import re
from pathlib import Path
from typing import TYPE_CHECKING, Annotated, cast

import tomlkit
import typer

from mex.release.emoji import pick_emoji

if TYPE_CHECKING:
    from tomlkit.items import Table

app = typer.Typer()

# one pull request entry in the notes generated by github, e.g.
# `* Update tooling by @RKIMetadataExchange in https://github.com/o/r/pull/919`
ENTRY = re.compile(r"^\* (?P<title>.+) by @(?P<author>\S+) in \S+/pull/\d+$")
# renovate updates of the language runtimes and package managers
RUNTIME = re.compile(
    r"^Update (?:dependency )?(?P<name>python|node(?:\.js)?|npm) to (?P<version>.+)$",
    flags=re.IGNORECASE,
)
# renovate updates of our own python packages
MEX_DEPENDENCY = re.compile(
    r"^Update dependency (?P<name>mex-[\w-]+) to (?P<version>\S+)"
)
# renovate updates of (compose) docker images, either to a new tag or a new digest
DOCKER = re.compile(
    r"^Update (?P<image>[^\s:]+)(?::(?P<tag>\S+))? "
    r"Docker (?P<kind>tag|digest) to (?P<version>\S+)"
)
# docker images that are build tooling, not dependencies worth announcing
SKIPPED_IMAGES = ("docker/dockerfile",)
# docker images of runtimes, whose digest updates are just upstream rebuilds
RUNTIME_IMAGES = ("python", "node")
# branch-like prefixes of human pull request titles, e.g. `feature/mx-1234-`
PREFIX = re.compile(r"^\w+/(?:me?x[-_ ]?\d+[-_ ]*)?", flags=re.IGNORECASE)
VERSION = re.compile(r"\d+(?:\.\d+)*")


def _version(text: str) -> str | None:
    """Extract the first version number, e.g. `3.15` from `>=3.15,<3.16`."""
    match = VERSION.search(text)
    return match.group() if match else None


def _version_key(version: str | None) -> tuple[int, ...]:
    """Make a version comparable."""
    return tuple(int(part) for part in version.split(".")) if version else ()


def _parse_docker(match: re.Match[str]) -> tuple[str, str | None] | None:
    """Turn a docker update into an image name and version, or None to skip it."""
    if match["image"] in SKIPPED_IMAGES:
        return None
    if match["kind"] == "tag":
        return match["image"].rsplit("/", 1)[-1], _version(match["version"])
    if not match["tag"] or match["image"] in RUNTIME_IMAGES:
        return None  # untagged digests or rebuilt runtime base images
    # digest updates keep the tag, e.g. `neo4j:2026.10.1-community`
    return match["image"].rsplit("/", 1)[-1], _version(match["tag"].split("-")[0])


def _parse_title(title: str, author: str, bot: str) -> tuple[str, str | None] | None:
    """Turn a pull request title into a name and version, or None to skip it."""
    if author != bot:
        feature = PREFIX.sub("", title).strip()
        if " " not in feature:
            # titles without spaces are probably branch names, e.g. `infra-to-tests`
            feature = re.sub(r"[-_]+", " ", feature)
        return (feature, None) if feature else None
    if match := RUNTIME.match(title):
        return match["name"].lower().removesuffix(".js"), _version(match["version"])
    if match := MEX_DEPENDENCY.match(title):
        return match["name"], _version(match["version"])
    if match := DOCKER.match(title):
        return _parse_docker(match)
    return None


def collect_features(notes: str, bot: str) -> list[str]:
    """Collect the noteworthy changes from release notes, in merge order."""
    features: dict[str, tuple[int, str, str | None]] = {}
    for position, line in enumerate(notes.splitlines()):
        if not (entry := ENTRY.match(line.strip())):
            continue
        if not (parsed := _parse_title(entry["title"], entry["author"], bot)):
            continue
        name, version = parsed
        known = features.get(name.lower())
        if known and _version_key(known[2]) > _version_key(version):
            continue  # keep only the highest version of each dependency
        features[name.lower()] = (position, name, version)
    return [
        f"{name} {version}" if version else name
        for _, name, version in sorted(features.values())
    ]


def render_announcement(heading: str, url: str, features: list[str]) -> str:
    """Render a chat announcement with a linked heading and a featuring line."""
    announcement = f"## [{heading}]({url})"
    if len(features) > 1:
        announcement += f"\n\nfeaturing {', '.join(features[:-1])} and {features[-1]}"
    elif features:
        announcement += f"\n\nfeaturing {features[0]}"
    return announcement


@app.command()
def get_announcement(
    ctx: typer.Context,
    notes: Annotated[
        typer.FileText,
        typer.Argument(help="Release notes generated by github, `-` for stdin"),
    ],
    repository: Annotated[
        str,
        typer.Option(envvar="GITHUB_REPOSITORY", help="Github repository owner/name"),
    ],
    bot: Annotated[
        str, typer.Option(envvar="MEX_BOT_USER", help="Github login of the bot user")
    ] = "RKIMetadataExchange",
) -> None:
    """Draft a chat announcement for the current release from its github notes."""
    root = cast("Path", ctx.obj.get("root"))
    with Path.open(root / "pyproject.toml") as f:
        project_data = cast("Table", tomlkit.load(f)["project"])
    name, version = project_data["name"], project_data["version"]
    _, emoji = pick_emoji(root)
    typer.echo(
        render_announcement(
            f"{name} {version} {emoji}",
            f"https://github.com/{repository}/releases/tag/{version}",
            collect_features(notes.read(), bot),
        )
    )
